SELECT json_build_object(
'identity',json_build_object('database',current_database(),'user',current_user,'version',current_setting('server_version'),'address',inet_server_addr(),'port',inet_server_port(),'is_standby',pg_is_in_recovery(),'transaction_read_only',current_setting('transaction_read_only'),'checked_at',current_timestamp),
'database', (SELECT json_build_object('owner',pg_get_userbyid(datdba),'is_template',datistemplate,'allow_connections',datallowconn) FROM pg_catalog.pg_database WHERE datname=current_database()),
'schemas',(SELECT coalesce(json_agg(json_build_object('name',nspname,'owner',pg_get_userbyid(nspowner)) ORDER BY nspname),'[]'::json) FROM pg_catalog.pg_namespace WHERE nspname !~ '^pg_' AND nspname<>'information_schema'),
'relations',(SELECT coalesce(json_agg(json_build_object('schema',n.nspname,'name',c.relname,'kind',c.relkind,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'estimated_rows',c.reltuples) ORDER BY n.nspname,c.relname),'[]'::json) FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname !~ '^pg_' AND n.nspname<>'information_schema' AND c.relkind IN ('r','p','v','m','f','S')),
'functions',(SELECT coalesce(json_agg(json_build_object('schema',n.nspname,'name',p.proname,'arguments',pg_catalog.oidvectortypes(p.proargtypes),'returns',pg_catalog.format_type(p.prorettype,NULL),'owner',pg_get_userbyid(p.proowner),'security_definer',p.prosecdef) ORDER BY n.nspname,p.proname),'[]'::json) FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN ('public','auth') AND p.prokind='f'),
'triggers',(SELECT coalesce(json_agg(json_build_object('schema',n.nspname,'relation',c.relname,'name',t.tgname,'enabled',t.tgenabled) ORDER BY n.nspname,c.relname,t.tgname),'[]'::json) FROM pg_catalog.pg_trigger t JOIN pg_catalog.pg_class c ON c.oid=t.tgrelid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname !~ '^pg_' AND n.nspname<>'information_schema' AND NOT t.tgisinternal),
'extensions',(SELECT coalesce(json_agg(json_build_object('name',extname,'version',extversion) ORDER BY extname),'[]'::json) FROM pg_catalog.pg_extension),
'prerequisites',json_build_object('auth_users',to_regclass('auth.users') IS NOT NULL,'auth_uid',to_regprocedure('auth.uid()') IS NOT NULL,'anon',EXISTS(SELECT 1 FROM pg_catalog.pg_roles WHERE rolname='anon'),'authenticated',EXISTS(SELECT 1 FROM pg_catalog.pg_roles WHERE rolname='authenticated'),'service_role',EXISTS(SELECT 1 FROM pg_catalog.pg_roles WHERE rolname='service_role'))
)
WHERE current_database()='thesis_connect_clean_validation' AND current_user='postgres' AND inet_server_port()=5433 AND inet_server_addr()='127.0.0.1'::inet AND current_setting('server_version')='17.11' AND NOT pg_is_in_recovery();
